function createEditablePolicy(policy: ReviewPolicyDraft | undefined): EditablePolicy {
  return {
    goal: policy?.goal ?? '',
    prohibitions: policy?.prohibitions ?? [],
    constraints: policy?.constraints ?? [],
  };
}

