  const commitLabel = contextResolution.resolvedCommitMessage?.trim()
    ? `${contextResolution.resolvedCommitSha.slice(0, 7)} (${contextResolution.resolvedCommitMessage.trim()})`
    : contextResolution.resolvedCommitSha.slice(0, 7);
