        response.end(JSON.stringify({ error: 'Invalid policyMode. Use auto or review.' }));
        return true;
      }

      const started = await startStudioNewReview({ policyMode, repoRoot: resolveRepoRootSafe() });
      response.statusCode = 200;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify(started));
      return true;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      response.statusCode = 500;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: `Failed to start review: ${message}` }));
      return true;
    }
  }

  if (!(requestUrl.pathname === '/api' || requestUrl.pathname.startsWith('/api/'))) {
    return false;
  }

  const targetUrl = new URL(`${requestUrl.pathname}${requestUrl.search}`, workerUrl);
  const method = (request.method ?? 'GET').toUpperCase();
  const headers = createProxyHeaders(request.headers, {
    apiKey,
    reviewGithubToken,
    openrouterApiKey,
  });

  const body = method === 'GET' || method === 'HEAD' ? undefined : new Uint8Array(await readBody(request));
  const upstream = await fetch(targetUrl.toString(), {
    method,
    headers,
    body,
  });

  response.statusCode = upstream.status;
  response.statusMessage = upstream.statusText;
  upstream.headers.forEach((value, key) => {
    if (key.toLowerCase() === 'transfer-encoding') {
      return;
    }
    response.setHeader(key, value);
  });

  if (!upstream.body || method === 'HEAD') {
    response.end();
    return true;
  }

  const reader = upstream.body.getReader();
  while (true) {
    const { done, value } = await reader.read();
    if (done) {
      break;
    }
    if (!value || value.byteLength === 0) {
      continue;
    }
    if (!response.write(Buffer.from(value))) {
      await once(response, 'drain');
    }
  }
  response.end();
  return true;
}

import * as p from '@clack/prompts';
import {
  clearStaleReviewStudioRuntimeMetadata,
  ensureReviewStudioRuntime,
  getReviewStudioRuntimeStatus,
  resolveReviewUiRuntimeContext,
  runStudioServeProcess,
  stopReviewStudioRuntime,
} from './session.js';
import { openBrowser } from './ui-server.js';

export interface OpenReviewFromCommitOptions {
  port?: number;
  commitish?: string;
  baseRef?: string;
  projectRoot?: string;
  idempotencyKey?: string;
  pollIntervalMs?: number;
}

export interface StartReviewStudioOptions {
  port?: number;
  routePath?: string;
  serve?: boolean;
  status?: boolean;
  stop?: boolean;
  devUi?: boolean;
  detach?: boolean;
}

export async function openReviewFromCommitCommand(options?: OpenReviewFromCommitOptions): Promise<void> {
  p.log.warning('`nimbus review open` is a compatibility path. Use `nimbus review studio` + `nimbus review create`.');
  const reviewModule = await import('./create-from-commit.js');
  await reviewModule.createReviewFromCommitCommand({
    commitish: options?.commitish,
    baseRef: options?.baseRef,
    projectRoot: options?.projectRoot,
    idempotencyKey: options?.idempotencyKey,
    pollIntervalMs: options?.pollIntervalMs,
    policyMode: 'review',
    openStudio: true,
    openStudioPort: options?.port,
  });
}

export async function startReviewStudioCommand(options?: StartReviewStudioOptions): Promise<void> {
  if (options?.serve) {
    const runtime = resolveReviewUiRuntimeContext({ port: options.port, preferDevUi: options.devUi });
    await runStudioServeProcess(runtime);
    return;
  }

  const runtime = resolveReviewUiRuntimeContext({ port: options?.port, preferDevUi: options?.devUi });
  if (options?.status) {
    const studioStatus = await getReviewStudioRuntimeStatus(runtime);
    if (studioStatus.running) {
      p.log.success(`Studio runtime is running at ${studioStatus.appUrl}`);
      if (studioStatus.runtime) {
        p.log.message(`PID: ${studioStatus.runtime.pid}`);
        p.log.message(`Started: ${studioStatus.runtime.startedAt}`);
      }
      return;
    }
    if (studioStatus.stale) {
      p.log.warning('Studio runtime metadata exists but runtime is not healthy.');
      return;
    }
    p.log.warning('Studio runtime is not running.');
    return;
  }

  if (options?.stop) {
    const stopped = await stopReviewStudioRuntime(runtime);
    if (stopped.stopped) {
      p.log.success('Stopped Studio runtime.');
      return;
    }
    if (stopped.stale) {
      p.log.warning('Studio runtime was stale. Cleared runtime metadata.');
      return;
    }
    p.log.warning('No running Studio runtime found for this repository.');
    return;
  }

  const routePath = options?.routePath ?? '/';
  const detach = options?.detach ?? Boolean(options?.routePath);
  if (!detach) {
    const appUrl = `http://127.0.0.1:${runtime.port}${routePath}`;
    const status = await getReviewStudioRuntimeStatus(runtime);
    if (status.running) {
      if (!status.runtime) {
        throw new Error(
          `Port ${runtime.port} is already in use by a non-Nimbus process. Use --port <n> or stop that process.`
        );
      }
      const stopped = await stopReviewStudioRuntime(runtime);
      if (!stopped.stopped) {
        if (stopped.stale) {
          throw new Error(
            `Could not stop existing Studio runtime on port ${runtime.port}. Runtime state is stale; run \`nimbus review studio --stop\` and retry.`
          );
        }
        throw new Error(
          `Could not stop existing Studio runtime on port ${runtime.port}. Please retry or use a different --port.`
        );
      }
      p.log.message('Stopped existing Studio runtime to start foreground session.');
    } else if (status.stale) {
      const cleared = await clearStaleReviewStudioRuntimeMetadata(runtime);
      if (cleared) {
        p.log.warning('Cleared stale Studio runtime metadata before foreground start.');
      }
    }

    openBrowser(appUrl);
    p.log.success(`Opened ${appUrl}`);
    await runStudioServeProcess(runtime);
    return;
  }

  const studio = await ensureReviewStudioRuntime(runtime, { routePath });
  openBrowser(studio.appUrl);
  p.log.success(`Opened ${studio.appUrl}`);
  p.log.message(studio.reused ? 'Reused existing Studio runtime.' : 'Started Studio runtime.');
}

