  useEffect(() => {
    let cancelled = false;
    const canRefresh = () => !cancelled && document.visibilityState === 'visible';
    const refresh = async () => {
      try {
        await Promise.all([fetchReviews(), fetchStudioContext()]);
      } catch (error) {
        if (!cancelled) {
          setErrorMessage(error instanceof Error ? error.message : String(error));
