 34	function clampText(value: string, maxBytes: number): { text: string; truncated: boolean } {
 35	  const encoder = new TextEncoder();
 36	  const bytes = encoder.encode(value);
 37	  if (bytes.byteLength <= maxBytes) {
 38	    return { text: value, truncated: false };
 39	  }
 40	  const sliced = bytes.slice(0, Math.max(0, maxBytes - 3));
 41	  return { text: new TextDecoder().decode(sliced) + '...', truncated: true };
 42	}
