   208	export async function streamReviewEvents(
   209	  workerUrl: string,
   210	  reviewId: string,
   211	  onEvent: (event: ReviewEventEnvelope) => void | Promise<void>
   212	): Promise<void> {
   213	  const response = await workerFetch(workerUrl, `${workerUrl}/api/reviews/${reviewId}/events`, {
   214	    headers: withReviewHeaders({
